function.arguments:
{"script": "result({
  "listing": repo.list("."),
  "src_listing": repo.list("src"),
  "nested": repo.list("src/nested"),
  "docs": repo.list("docs"),
  "hits": repo.search("slow_path", glob = "**"),
})"}

{"script": "res = env.run(["find", "src", "-type", "f"], check=False)
res2 = env.run(["grep", "-rn", "slow", "src"], check=False)
res3 = env.run(["git", "status", "--porcelain"], check=False)
result({
  "find": res.stdout,
  "grep_slow": res2.stdout,
  "grep_stderr": res2.stderr,
  "git_status": res3.stdout,
})"}

{"script": "repo.edit("src/a.txt", "slow_path", "fast_path", all = True)
repo.edit("src/nested/b.txt", "slow_path", "fast_path", all = True)

result({
  "a": repo.read("src/a.txt"),
  "b": repo.read("src/nested/b.txt"),
  "untouched": repo.read("src/untouched.txt"),
  "docs": repo.read("docs/history.txt"),
  "status": repo.status(),
})"}

{"script": "res = env.run(["git", "diff"], check=False)
res2 = env.run(["grep", "-rn", "slow_path", "."], check=False)
res3 = env.run(["grep", "-rn", "fast_path", "."], check=False)
result({
  "diff": res.stdout,
  "remaining_slow_path": res2.stdout,
  "fast_path_occurrences": res3.stdout,
})"}

{"script": "res = env.run(["git", "rev-parse", "--is-inside-work-tree"], check = False)
res2 = env.run(["wc", "-c", "src/a.txt", "src/nested/b.txt", "src/untouched.txt", "docs/history.txt"], check = False)
res3 = env.run(["od", "-c", "src/a.txt"], check = False)
result({
  "is_git_repo": res.stdout.strip(),
  "git_stderr": res.stderr.strip(),
  "wc": res2.stdout,
  "od_a": res3.stdout,
  "tool_diff": repo.diff(),
})"}
